eason": "Tuyệt đối không sai sót về chính sách giá và bảo hành 7-10 năm.", "improvementTip": "Tiếp tục duy trì phong độ cập nhật văn bản bán hàng mới nhất."}, {"criterion": "closing_next_step", "criterionNameVi": "Chốt đơn & Bước tiếp theo (Closing / Next Step)", "score_5": 5, "score": 100, "maxScore": 100, "definition": "Thúc đẩy bước tiếp theo: Đặt cọc giữ xe hoặc mời lái thử thực tế.", "evidence": ["Đã đưa ra lời mời lái thử và đăng ký giữ xe cụ thể."], "reason": "Đã có hành động chốt và hướng khách tới trải nghiệm thực tế.", "improvementTip": "Áp dụng kỹ năng chốt bằng lựa chọn thay thế (màu xe, ngày nhận xe)."}]','Tư vấn viên đạt kết quả 88/100. Nắm vững kiến thức sản phẩm và chính sách bảo hành pin VinFast.','[{"id": "msg-bd9dbb", "sender": "customer", "text": "Chào cậu, tôi đang tìm một chiếc SUV cỡ lớn êm ái để đi tiếp khách và đi đánh golf. Với tầm giá hơn 2 tỷ, bạn bè tôi bảo mua Ford Explorer hay Lexus cho sang, đối tác nhìn vào VF 9 có nghĩ tôi mua xe taxi không?", "timestamp": "13:09"}, {"id": "msg-122848", "sender": "advisor", "text": "Dạ em chào anh/chị, cho em hỏi mình thường di chuyển massage thế nào ạ?", "timestamp": "13:09", "intentDetected": "Đặt câu hỏi khai thác nhu cầu thành công"}, {"id": "msg-176c24", "sender": "customer", "text": "Tôi hay bị đau lưng sau những chuyến đi dài, rất cần ghế thương gia massage chuyên sâu và điều hòa độc lập.", "timestamp": "13:09"}, {"id": "msg-ce4ee9", "sender": "advisor", "text": "Dạ xe VinFast có bảo hành pin và đổi pin mới 100% khi dung lượng SOH dưới 70%, lại được miễn 100% lệ phí trước bạ cực kỳ tiết kiệm ạ!", "timestamp": "13:09", "intentDetected": "Đưa ra luận điểm giải tỏa băn khoăn & tư vấn chính sách"}, {"id": "msg-c6c8a4", "sender": "customer", "text": "Cậu giải thích nghe có lý. Nhưng xe điện đi tiếp khách ngoại giao thì đối tác nhìn vào có đánh giá không?", "timestamp": "13:09"}, {"id": "msg-9843ce", "sender": "advisor", "text": "Em mời anh/chị cuối tuần này ghé showroom lái thử trải nghiệm thực tế xe và đặt cọc giữ xe nhận ưu đãi luôn nhé!", "timestamp": "13:09", "intentDetected": "Đề xuất chốt đơn & Lái thử trải nghiệm"}, {"id": "msg-739ce9", "sender": "customer", "text": "Được rồi, cậu cho người đưa xe VF 9 qua cơ quan tôi vào sáng thứ Bảy này để tôi và tài xế cùng lái thử nhé.", "timestamp": "13:09"}]','Luyện tập thêm kịch bản khách hàng so sánh công nghệ ADAS để tăng tốc độ phản xạ.',0,NULL,NULL,NULL,NULL);
INSERT INTO "session_evaluations" VALUES('eval-4d3ac2','SCENARIO_06_VF3_FIRST_CAR','VF 3 — Khách hàng trẻ nâng cấp từ xe máy lên ô tô, lo lội nước & chi phí','VF 3','eval-adv','Kiểm Thử Viên','27/09/2026 13:09','8 phút',88,4.0,1,'[{"criterion": "need_discovery", "criterionNameVi": "Thấu hiểu nhu cầu (Need Discovery)", "score_5": 4, "score": 80, "maxScore": 100, "definition": "Khai thác thói quen di chuyển thực tế, quy mô tài chính và nhu cầu sử dụng xe của khách.", "evidence": ["Tư vấn viên đã chủ động đặt câu hỏi tìm hiểu quãng đường di chuyển của khách."], "reason": "Khai thác được 1/2 thông tin nhu cầu ẩn.", "improvementTip": "Chủ động hỏi thêm về điều kiện sạc pin tại gia đình/chung cư sớm hơn."}, {"criterion": "product_knowledge", "criterionNameVi": "Kiến thức sản phẩm (Product Knowledge)", "score_5": 3, "score": 60, "maxScore": 100, "definition": "Nắm vững thông số công suất, quãng đường di chuyển và thời gian sạc nhanh của xe VinFast.", "evidence": ["Chưa lồng ghép đủ số liệu kỹ thuật thuyết phục vào câu trả lời."], "reason": "Thông số chuẩn xác, không bị nhầm lẫn giữa các phiên bản.", "improvementTip": "Lồng ghép thêm thông số khoảng sáng gầm xe để tăng tính thuyết phục."}, {"criterion": "objection_handling", "criterionNameVi": "Xử lý từ chối (Objection Handling)", "score_5": 5, "score": 100, "maxScore": 100, "definition": "Hóa giải băn khoăn về chi phí pin, độ chai pin và so sánh với xe xăng.", "evidence": ["Hóa giải thành công băn khoăn về pin bằng chính sách cam kết đổi mới khi SOH dưới 70%."], "reason": "Biến điểm yếu tâm lý thành lợi thế bảo hành trọn đời an tâm.", "improvementTip": "Cần đồng cảm trước khi đưa ra các con số phản biện."}, {"criterion": "policy_accuracy", "criterionNameVi": "Độ chính xác chính sách (Policy Accuracy)", "score_5": 5, "score": 100, "maxScore": 100, "definition": "Cập nhật chính xác ưu đãi trước bạ 0% và chương trình sạc miễn phí V-GREEN.", "evidence": ["Nêu chính xác Nghị định miễn 100% lệ phí trước bạ xe điện và mạng lưới trạm sạc V-GREEN."], "reason": "Tuyệt đối không sai sót về chính sách giá và bảo hành 7-10 năm.", "improvementTip": "Tiếp tục duy trì phong độ cập nhật văn bản bán hàng mới nhất."}, {"criterion": "closing_next_step", "criterionNameVi": "Chốt đơn & Bước tiếp theo (Closing / Next Step)", "score_5": 5, "score": 100, "maxScore": 100, "definition": "Thúc đẩy bước tiếp theo: Đặt cọc giữ xe hoặc mời lái thử thực tế.", "evidence": ["Đã đưa ra lời mời lái thử và đăng ký giữ xe cụ thể."], "reason": "Đã có hành động chốt và hướng khách tới trải nghiệm thực tế.", "improvementTip": "Áp dụng kỹ năng chốt bằng lựa chọn thay thế (màu xe, ngày nhận xe)."}]','Tư vấn viên đạt kết quả 88/100. Nắm vững kiến thức sản phẩm và chính sách bảo hành pin VinFast.','[{"id": "msg-f04bbd", "sender": "customer", "text": "Chào bạn, mình đang đi xe máy Vespa thấy trời mưa bão ngập lụt sợ quá nên tính gom góp mua chiếc VF 3. Nhưng mình là con gái chưa lái ô tô bao giờ, xe này lội nước có bị giật điện không và mỗi tháng nuôi xe hết nhiều tiền không bạn?", "timestamp": "13:09"}, {"id": "msg-320611", "sender": "advisor", "text": "Dạ em chào anh/chị, cho em hỏi mình thường di chuyển tuyến đường thế nào ạ?", "timestamp": "13:09", "intentDetected": "Đặt câu hỏi khai thác nhu cầu thành công"}, {"id": "msg-2ec2b7", "sender": "customer", "text": "Đoạn đường Nguyễn Trãi mình đi làm cứ mưa rào là ngập sâu đến ống chân, xe máy chết máy dắt bộ khổ lắm bạn ạ.", "timestamp": "13:09"}, {"id": "msg-f3b4ea", "sender": "advisor", "text": "Dạ xe VinFast có bảo hành pin và đổi pin mới 100% khi dung lượng SOH dưới 70%, lại được miễn 100% lệ phí trước bạ cực kỳ tiết kiệm ạ!", "timestamp": "13:09", "intentDetected": "Đưa ra luận điểm giải tỏa băn khoăn & tư vấn chính sách"}, {"id": "msg-c7988f", "sender": "customer", "text": "À, nghĩa là chai pin dưới 70% là được đổi pin mới miễn phí luôn à? Thế chi phí bảo dưỡng xe điện so với xe xăng thì chênh lệch thế nào em?", "timestamp": "13:09"}, {"id": "msg-36e615", "sender": "advisor", "text": "Em mời anh/chị cuối tuần này ghé showroom lái thử trải nghiệm thực tế xe và đặt cọc giữ xe nhận ưu đãi luôn nhé!", "timestamp": "13:09", "intentDetected": "Đề xuất chốt đơn & Lái thử trải nghiệm"}, {"id": "msg-635088", "sender": "customer", "text": "Nghe em phân tích rõ ràng và minh bạch anh thấy rất an tâm. Cho anh đăng ký lái thử và gửi hợp đồng cọc giữ xe luôn nhé!", "timestamp": "13:09"}]','Luyện tập thêm kịch bản khách hàng so sánh công nghệ ADAS để tăng tốc độ phản xạ.',0,NULL,NULL,NULL,NULL);
