ôn nhé!", "timestamp": "13:11", "intentDetected": "Đề xuất chốt đơn & Lái thử trải nghiệm"}, {"id": "msg-5aedd3", "sender": "customer", "text": "Nghe chú em giải thích rành rọt rứa tui ưng cấy bụng rồi nợ! Cuối tuần cho tui ghé VinFast Vinh lái thử con xe nhé.", "timestamp": "13:11"}]','Luyện tập thêm kịch bản khách hàng so sánh công nghệ ADAS để tăng tốc độ phản xạ.',0,NULL,NULL,NULL,NULL);
INSERT INTO "session_evaluations" VALUES('sess-647c6252','SCENARIO_01_VF5_TAXI','Bác tài chạy dịch vụ cân nhắc đổi từ xe xăng sang VF 5 Plus','VinFast','adv-001','Võ Trường An','27/09/2026 13:16','4 phút',72,4.0,1,'[{"criterion": "need_discovery", "criterionNameVi": "Thấu hiểu nhu cầu (Need Discovery)", "score_5": 4, "score": 80, "maxScore": 100, "definition": "Khai thác thói quen di chuyển thực tế, quy mô tài chính và nhu cầu sử dụng xe của khách.", "evidence": ["Tư vấn viên đã chủ động đặt câu hỏi tìm hiểu quãng đường di chuyển của khách."], "reason": "Khai thác được 1/2 thông tin nhu cầu ẩn.", "improvementTip": "Chủ động hỏi thêm về điều kiện sạc pin tại gia đình/chung cư sớm hơn."}, {"criterion": "product_knowledge", "criterionNameVi": "Kiến thức sản phẩm (Product Knowledge)", "score_5": 5, "score": 100, "maxScore": 100, "definition": "Nắm vững thông số công suất, quãng đường di chuyển và thời gian sạc nhanh của xe VinFast.", "evidence": ["Trình bày chính xác thông số vận hành, thời gian sạc nhanh và chuẩn chống nước."], "reason": "Thông số chuẩn xác, không bị nhầm lẫn giữa các phiên bản.", "improvementTip": "Lồng ghép thêm thông số khoảng sáng gầm xe để tăng tính thuyết phục."}, {"criterion": "objection_handling", "criterionNameVi": "Xử lý từ chối (Objection Handling)", "score_5": 3, "score": 60, "maxScore": 100, "definition": "Hóa giải băn khoăn về chi phí pin, độ chai pin và so sánh với xe xăng.", "evidence": ["Cần phản biện thuyết phục hơn về băn khoăn chi phí thuê pin."], "reason": "Biến điểm yếu tâm lý thành lợi thế bảo hành trọn đời an tâm.", "improvementTip": "Cần đồng cảm trước khi đưa ra các con số phản biện."}, {"criterion": "policy_accuracy", "criterionNameVi": "Độ chính xác chính sách (Policy Accuracy)", "score_5": 4, "score": 80, "maxScore": 100, "definition": "Cập nhật chính xác ưu đãi trước bạ 0% và chương trình sạc miễn phí V-GREEN.", "evidence": ["Đã nắm chính sách nhưng chưa nêu bật quyền lợi sạc pin miễn phí."], "reason": "Tuyệt đối không sai