INSERT INTO "session_messages" VALUES('msg-99e0e4','eval-78c9e9','advisor','Dạ xe VinFast có bảo hành pin và đổi pin mới 100% khi dung lượng SOH dưới 70%, lại được miễn 100% lệ phí trước bạ cực kỳ tiết kiệm ạ!','13:16','Đưa ra luận điểm giải tỏa băn khoăn & tư vấn chính sách');
INSERT INTO "session_messages" VALUES('msg-458b2f','eval-78c9e9','customer','À, nghĩa là chai pin dưới 70% là được đổi pin mới miễn phí luôn à? Thế chi phí bảo dưỡng xe điện so với xe xăng thì chênh lệch thế nào em?','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-cd1856','eval-78c9e9','advisor','Em mời anh/chị cuối tuần này ghé showroom lái thử trải nghiệm thực tế xe và đặt cọc giữ xe nhận ưu đãi luôn nhé!','13:16','Đề xuất chốt đơn & Lái thử trải nghiệm');
INSERT INTO "session_messages" VALUES('msg-e02c07','eval-78c9e9','customer','Nghe em phân tích rõ ràng và minh bạch anh thấy rất an tâm. Cho anh đăng ký lái thử và gửi hợp đồng cọc giữ xe luôn nhé!','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-34d7d6','eval-1210e0','customer','Hello! I am an expat living in Vietnam and considering the VF 8 Plus. What are the legal requirements for a foreigner to register and own a VinFast car here? Does the vehicle support full English voice control for my family?','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-cc937f','eval-1210e0','advisor','Dạ em chào anh/chị, cho em hỏi mình thường di chuyển trc thế nào ạ?','13:16','Đặt câu hỏi khai thác nhu cầu thành công');
INSERT INTO "session_messages" VALUES('msg-dc5baf','eval-1210e0','customer','I have a valid 3-year Temporary Residence Card (TRC), valid passport, and an official work permit in Hanoi.','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-072c6b','eval-1210e0','advisor','Dạ xe VinFast có bảo hành pin và đổi pin mới 100% khi dung lượng SOH dưới 70%, lại được miễn 100% lệ phí trước bạ cực kỳ tiết kiệm ạ!','13:16','Đưa ra luận điểm giải tỏa băn khoăn & tư vấn chính sách');
INSERT INTO "session_messages" VALUES('msg-7a24cf','eval-1210e0','customer','Alright, and what about the legal paperworks for the Temporary Residence Card registration?','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-a13ba0','eval-1210e0','advisor','Em mời anh/chị cuối tuần này ghé showroom lái thử trải nghiệm thực tế xe và đặt cọc giữ xe nhận ưu đãi luôn nhé!','13:16','Đề xuất chốt đơn & Lái thử trải nghiệm');
INSERT INTO "session_messages" VALUES('msg-06ee4c','eval-1210e0','customer','That sounds very reasonable and convincing! Please book me a test drive this Saturday morning and send the quotation.','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-e97847','eval-7127f4','customer','Chào chú em! Tui đang ngó con VF 5 ni đặng chạy khách tuyến Vinh - Cửa Lò. Mà ngặt nỗi pin ni chạy có bị chai hông chú, với lỡ đang chạy giữa đàng mà hết điện thì mần răng hả chú?','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-ac2de5','eval-7127f4','advisor','Dạ em chào anh/chị, cho em hỏi mình thường di chuyển cửa lò thế nào ạ?','13:16','Đặt câu hỏi khai thác nhu cầu thành công');
INSERT INTO "session_messages" VALUES('msg-7777e4','eval-7127f4','customer','Mỗi ngày tui chạy túc tắc tuyến đường 72m ra Cửa Lò với vô đền Bác tầm 150 cây số chú nợ.','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-a3e46e','eval-7127f4','advisor','Dạ xe VinFast có bảo hành pin và đổi pin mới 100% khi dung lượng SOH dưới 70%, lại được miễn 100% lệ phí trước bạ cực kỳ tiết kiệm ạ!','13:16','Đưa ra luận điểm giải tỏa băn khoăn & tư vấn chính sách');
INSERT INTO "session_messages" VALUES('msg-f0c1a5','eval-7127f4','customer','Rứa thì tiền điện sạc mỗi tháng tính ra có đỡ hơn tiền dầu chạy xe cũ hông chú?','13:16',NULL);
INSERT INTO "session_messages" VALUES('msg-d2cddf','eval-7127f4','advisor','Em mời anh/chị cuối tuần này ghé showroom lái thử trải nghiệm thực tế xe và đặt cọc giữ xe nhận ưu đãi luôn nhé!','13:16','Đề xuất chốt đơn & Lái thử trải nghiệm');
INSERT INTO "session_messages" VALUES('msg-3f6580','eval-7127f4','customer','Nghe chú em giải thích rành rọt rứa tui ưng cấy bụng rồi nợ! Cuối tuần cho tui ghé VinFast Vinh lái thử con xe nhé.','13:16',NULL);
