-- ==========================================================
-- VINFAST AI ENABLEMENT COACH (VFO2O-20) - SQL DUMP
-- Database: SQLite 3 / SQLAlchemy Compatible
-- ==========================================================

BEGIN TRANSACTION;
CREATE TABLE practice_sessions (
	session_id VARCHAR(60) NOT NULL, 
	scenario_id VARCHAR(60) NOT NULL, 
	scenario_title VARCHAR(200) NOT NULL, 
	vehicle_model VARCHAR(50) NOT NULL, 
	advisor_id VARCHAR(50) NOT NULL, 
	advisor_name VARCHAR(100) NOT NULL, 
	turn_count INTEGER, 
	trust_level INTEGER, 
	interest_level INTEGER, 
	conversation_stage VARCHAR(30), 
	status VARCHAR(30), 
	revealed_facts_json TEXT, 
	resolved_objections_json TEXT, 
	created_at VARCHAR(50), 
	updated_at VARCHAR(50), 
	PRIMARY KEY (session_id)
);
CREATE TABLE session_evaluations (
	session_id VARCHAR(60) NOT NULL, 
	scenario_id VARCHAR(60) NOT NULL, 
	scenario_title VARCHAR(200) NOT NULL, 
	vehicle_model VARCHAR(50) NOT NULL, 
	advisor_id VARCHAR(50) NOT NULL, 
	advisor_name VARCHAR(100) NOT NULL, 
	date VARCHAR(50) NOT NULL, 
	duration VARCHAR(30) NOT NULL, 
	overall_score INTEGER NOT NULL, 
	overall_score_5 FLOAT NOT NULL, 
	passed BOOLEAN, 
	rubric_breakdown_json TEXT NOT NULL, 
	ai_summary TEXT NOT NULL, 
	transcript_json TEXT NOT NULL, 
	recommended_next_practice TEXT, 
	manager_reviewed BOOLEAN, 
	manager_score INTEGER, 
	manager_note TEXT, 
	reviewed_by VARCHAR(100), 
	reviewed_at VARCHAR(50), 
	PRIMARY KEY (session_id)
);
CREATE TABLE session_messages (
	id VARCHAR(60) NOT NULL, 
	session_id VARCHAR(60) NOT NULL, 
	sender VARCHAR(20) NOT NULL, 
	text TEXT NOT NULL, 
	timestamp VARCHAR(20) NOT NULL, 
	intent_detected VARCHAR(100), 
	PRIMARY KEY (id)
);
CREATE TABLE telemetry_events (
	id INTEGER NOT NULL, 
	event_name VARCHAR(100) NOT NULL, 
	payload_json TEXT NOT NULL, 
	created_at VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE TABLE training_assignments (
	id VARCHAR(50) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	scenario_title VARCHAR(200) NOT NULL, 
	target_vehicle VARCHAR(50) NOT NULL, 
	assigned_to_advisor VARCHAR(100) NOT NULL, 
	assigned_by_manager VARCHAR(100) NOT NULL, 
	due_date VARCHAR(30) NOT NULL, 
	status VARCHAR(20), 
	score INTEGER, 
	created_at VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE TABLE users (
	id VARCHAR(50) NOT NULL, 
	email VARCHAR(100) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	phone VARCHAR(20), 
	role VARCHAR(20) NOT NULL, 
	avatar VARCHAR(255), 
	title VARCHAR(100), 
	department VARCHAR(100), 
	showroom VARCHAR(100), 
	status VARCHAR(20), 
	account_status VARCHAR(20), 
	password_hash VARCHAR(128) NOT NULL, 
	created_at VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_practice_sessions_advisor_id ON practice_sessions (advisor_id);
CREATE INDEX ix_practice_sessions_scenario_id ON practice_sessions (scenario_id);
CREATE INDEX ix_session_messages_session_id ON session_messages (session_id);
CREATE INDEX ix_session_evaluations_advisor_id ON session_evaluations (advisor_id);
CREATE INDEX ix_telemetry_events_event_name ON telemetry_events (event_name);
COMMIT;
